mapper.select:
select count(*) from sys_invitation_code
where create_uid = #{userId}
and (expired_time is null or expired_time > CURRENT_TIMESTAMP)

select ic.*, p.P_Name as p_name,
case when ic.expired_time <= CURRENT_TIMESTAMP then 1 else 0 end as expired
from sys_invitation_code ic
left join Pre_Project p on p.P_Id = ic.p_id

    and ic.create_uid = #{request.createUid}
    
        and ic.p_id = #{request.pId}
    
    
        and INSTR(p.P_Name, #{request.pName}) > 0
    
    
        and ic.id = #{request.id}
    
    
        and INSTR(ic.code, #{request.code}) > 0
    
    
        and INSTR(ic.create_uname, #{request.createUname}) > 0
    
    
        and ic.create_time = #{request.createTime}
    
    
        and ic.expired_time = #{request.expiredTime}
    
    
        and ic.create_time >= #{request.createTimeStart}
    
    
        and ic.create_time <= #{request.createTimeEnd}
    
    
        and ic.expired_time >= #{request.expiredTimeStart}
    
    
        and ic.expired_time <= #{request.expiredTimeEnd}
    
    
        
            
                and ic.expired_time <= CURRENT_TIMESTAMP
            
            
                and (ic.expired_time is null or ic.expired_time > CURRENT_TIMESTAMP)
            
        
    

order by ic.create_time desc, ic.id desc
